col_refs = {}
for alias, aggregate in aggregates.items():
    replacements = {}
    for col in self._gen_cols([aggregate], resolve_refs=False):
        if not (col_ref := col_refs.get(col)):
            index = len(col_refs) + 1
            col_alias = f"__col{index}"
            col_ref = Ref(col_alias, col)
            col_refs[col] = col_ref
            inner_query.annotations[col_alias] = col
            inner_query.append_annotation_mask([col_alias])
        replacements[col] = col_ref
    outer_query.annotations[alias] = aggregate.replace_expressions(
        replacements
    )
# Aggregates cannot be computed over window functions as the
# latter are evaluated after grouping. Any window annotation
# referenced by an aggregate must therefore be materialized in the
# inner query and referenced from the outer query.
for alias, aggregate in aggregates.items():
    if not aggregate.contains_over_clause:
        continue
    replacements = {}
    for ref in aggregate.get_refs():
        annotation = self.annotations.get(ref)
        if annotation is None or not annotation.contains_over_clause:
            continue
        if ref not in inner_query.annotations:
            inner_query.annotations[ref] = annotation
        inner_query.append_annotation_mask([ref])
        replacements[Ref(ref, annotation)] = Ref(ref, annotation)
    if replacements:
        outer_query.annotations[alias] = (
            outer_query.annotations[alias].replace_expressions(
                replacements
            )
        )

